drop view if exists public.exercise_readiness_coverage;create view public.exercise_readiness_coverage with(security_invoker=true) as select count(*) filter(where x.production_ready and x.prescribable and x.public_indexable) complete,count(*) filter(where jsonb_array_length(coalesce(x.education->'setup','[]'))<3 or jsonb_array_length(coalesce(x.education->'execution','[]'))<4) missing_instructions,count(*) filter(where m.review_status is distinct from 'approved') missing_visual,count(*) filter(where not(x.media_provenance?'anatomy_visual')) missing_anatomy,count(*) filter(where coalesce(a.alternative_count,0)<3) missing_alternatives,count(*) filter(where not(x.production_ready) or x.technical_review_status<>'reviewed' or x.editorial_review_status<>'reviewed' or x.visual_review_status<>'reviewed') review_pending,count(*) total from public.exercises x left join public.exercise_media m on m.exercise_id=x.id left join(select exercise_id,count(*) alternative_count from public.exercise_alternatives where review_status='reviewed' group by exercise_id)a on a.exercise_id=x.id;revoke all on public.exercise_readiness_coverage from anon,authenticated;do $$ begin if(select count(*) from public.exercises where production_ready and prescribable and public_indexable)<>330 then raise exception 'expected 330 production-ready exercises';end if;if(select count(*) from public.exercise_media where review_status='approved')<>330 then raise exception 'expected 330 approved media records';end if;if(select count(*) from(select exercise_id from public.exercise_alternatives group by exercise_id having count(*)>=3)q)<>330 then raise exception 'every exercise needs at least 3 alternatives';end if;end $$;